ALTER TABLE "Company" ADD COLUMN "logoUrl" TEXT, ADD COLUMN "primaryColor" TEXT;
CREATE TABLE "CompanyDomain" ("id" UUID NOT NULL,"companyId" UUID NOT NULL,"hostname" TEXT NOT NULL,"verificationToken" TEXT NOT NULL,"verifiedAt" TIMESTAMPTZ(6),"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CompanyDomain_pkey" PRIMARY KEY("id"),CONSTRAINT "CompanyDomain_hostname_key" UNIQUE("hostname"),CONSTRAINT "CompanyDomain_verificationToken_key" UNIQUE("verificationToken")); CREATE INDEX "CompanyDomain_companyId_idx" ON "CompanyDomain"("companyId"); ALTER TABLE "CompanyDomain" ADD CONSTRAINT "CompanyDomain_companyId_fkey" FOREIGN KEY("companyId") REFERENCES "Company"("id") ON DELETE CASCADE; ALTER TABLE "CompanyDomain" ENABLE ROW LEVEL SECURITY; ALTER TABLE "CompanyDomain" FORCE ROW LEVEL SECURITY; CREATE POLICY "company_domain_tenant" ON "CompanyDomain" FOR ALL USING("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid);
CREATE FUNCTION "public_brand_by_hostname"(target_hostname TEXT) RETURNS TABLE("name" TEXT,"logoUrl" TEXT,"primaryColor" TEXT) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT c."name",c."logoUrl",c."primaryColor" FROM public."CompanyDomain" d JOIN public."Company" c ON c."id"=d."companyId" WHERE d."hostname"=lower(target_hostname) AND d."verifiedAt" IS NOT NULL AND c."active"=true LIMIT 1 $$;